import httpx

_etags: dict[str, str] = {}


async def poll(client, repos):
    for repo in repos:
        headers = {}
        if repo in _etags:
            headers['If-None-Match'] = _etags[repo]
        r = await client.get(f'https://api.github.com/repos/{repo}/events', headers=headers)
        if r.status_code == 304:
            continue
        _etags[repo] = r.headers.get('ETag', '')
